airport_perf:
SELECT
  airport_code,
  COUNTIF(movement_type = 'D') AS departures,
  COUNTIF(movement_type = 'A') AS arrivals,
  ROUND(AVG(CASE WHEN movement_type = 'D' AND delay_minutes BETWEEN -180 AND 600 THEN delay_minutes END), 1) AS avg_departure_delay,
  ROUND(AVG(CASE WHEN movement_type = 'A' AND delay_minutes BETWEEN -180 AND 600 THEN delay_minutes END), 1) AS avg_arrival_delay,
  ROUND(SAFE_DIVIDE(COUNTIF(NOT is_cancelled AND delay_minutes <= 0), COUNT(*)) * 100, 1) AS on_time_pct,
  ROUND(SAFE_DIVIDE(COUNTIF(is_cancelled), COUNT(*)) * 100, 1) AS cancellation_pct
FROM marts.flights_performance
WHERE {{ filter_date_range('flight_date', 'date_range') }}
  AND {{ filter('airline_name', 'airline') }}
  AND {{ filter('airport_code', 'airport') }}
  AND {{ filter('flight_direction', 'direction') }}
  AND {{ filter('time_of_day', 'time_of_day') }}
  AND {{ filter('delay_category', 'delay_category') }}
GROUP BY airport_code
ORDER BY (departures + arrivals) DESC

delay_distribution:
SELECT
  delay_category,
  COUNT(*) AS total_flights,
  ROUND(SAFE_DIVIDE(COUNT(*), SUM(COUNT(*)) OVER ()) * 100, 1) AS pct,
  ROUND(AVG(delay_minutes), 1) AS avg_delay_minutes
FROM marts.flights_performance
WHERE {{ filter_date_range('flight_date', 'date_range') }}
  AND {{ filter('airline_name', 'airline') }}
  AND {{ filter('airport_code', 'airport') }}
  AND {{ filter('flight_direction', 'direction') }}
  AND {{ filter('time_of_day', 'time_of_day') }}
  AND delay_category IS NOT NULL
GROUP BY delay_category
ORDER BY total_flights DESC

